import {legacyReportCandidates} from '../../src/main/cloud-plan-contract.mjs';
import fs from 'node:fs';

const serverAccountSizing = JSON.parse(fs.readFileSync(new URL('../fixtures/cloud-entry-account-sizing.json', import.meta.url), 'utf8'));

// positionSizing is generated by the real server risk_check, not by the card
// implementation. In particular, it has no legacy side/entry/stop/targets.
export function cloudAccountPlanCardFixture(locale='zh-CN', direction='long') {
  const report=cloudPlanCardFixture(locale),plan=report.executionPlan;
  const source=structuredClone(serverAccountSizing.scenarios[direction]);
  Object.assign(plan.entryCondition, {direction,
    trigger:{operator:direction==='long'?'cross_up':'cross_down',lower:source.entry},
    invalidation:{operator:direction==='long'?'at_or_below':'at_or_above',lower:source.stop}});
  Object.assign(plan.scenarios[0],source,{eligible:true,confirmation:'bar_close',
    entryCondition:structuredClone(plan.entryCondition),riskReward:[...source.positionSizing.netRiskReward]});
  plan.positionSizing=structuredClone(source.positionSizing);
  report.planRecords[0].scenario=structuredClone(plan.scenarios[0]);
  return report;
}

export function cloudPlanCardFixture(locale='zh-CN') {
  const uuid=n=>`00000000-0000-4000-8000-${String(n).padStart(12,'0')}`;
  const conditionHash='a'.repeat(64);
  const scenario={stop:81682.2,targets:[83207.45,83512.5],conditionHash};
  return {schemaVersion:1,runId:uuid(1),resultHash:'b'.repeat(64),locale,
    marketId:'BINANCE:FUTURES:BTCUSDT',interval:'60',strategyId:'price-action',report:'Frozen cloud report',
    executionPlan:{schemaVersion:2,planId:uuid(2),createdAt:1792326741009,requestedMode:'auto',selectedMode:'right',conditionHash,outcome:{action:'plan'},
      entryCondition:{conditionId:uuid(3),revision:1,direction:'long',interval:'1h',confirmation:'bar_close',
        trigger:{operator:'cross_up',lower:82292.3},invalidation:{operator:'at_or_below',lower:81682.2},expiresAt:Date.parse('2026-10-18T15:32:21.009Z')},scenarios:[scenario]},
    planRecords:[{id:uuid(2),runId:uuid(1),version:1,confirmationHash:'c'.repeat(64),monitoringPolicy:'entry_v2',scenario,expiresAt:Date.parse('2026-10-18T15:32:21.009Z'),status:'pending',createdAt:'2026-10-18T12:32:21.009Z'}]};
}

export function legacyCloudPlanCardFixture(strategyId,locale='zh-CN',direction='long') {
  const report=cloudPlanCardFixture(locale);
  report.strategyId=strategyId;report.executionPolicy='right-legacy-v1';
  report.report=`### BTC/USDT Binance Perpetual 1H · ${direction==='long'?'Long':'Short'} conditional plan
Direction: ${direction==='long'?'Long':'Short'}
Strategy: ${strategyId}
Entry trigger: 82292.3
Stop-loss and invalidation: 81682.2
Take-profit targets: Target 1: 83207.45; Target 2: 83512.5
Risk/reward: Target 1: 1:1.5; Target 2: 1:2`;
  const card=legacyReportCandidates(report.report)[0];
  if(!card)throw new Error('Legacy fixture did not yield a concrete card');
  report.executionPlan={schemaVersion:1,scenarios:[{side:direction,entry:82292.3,stop:81682.2,targets:[83207.45,83512.5]}]};
  Object.assign(report.planRecords[0],{executionPolicy:'right-legacy-v1',monitoringPolicy:'windows_v1',cardIndex:0,card:{title:card.title,content:card.content}});
  return report;
}
